import { createHmac, timingSafeEqual } from 'node:crypto';

export async function handler(req: Request): Promise<Response> {
  const signature = req.headers.get('x-webflow-signature') ?? '';
  const timestamp = req.headers.get('x-webflow-timestamp') ?? '';
  const raw = await req.text();

  // Reject replays before doing any work. Without this a captured request
  // can be resent indefinitely.
  if (Math.abs(Date.now() - Number(timestamp)) > 5 * 60_000) {
    return new Response('Stale', { status: 401 });
  }

  const expected = createHmac('sha256', process.env.WEBFLOW_SECRET!)
    .update(`${timestamp}:${raw}`)
    .digest();

  const provided = Buffer.from(signature, 'hex');
  // timingSafeEqual, not ===: string comparison leaks how much matched.
  if (provided.length !== expected.length || !timingSafeEqual(provided, expected)) {
    return new Response('Bad signature', { status: 401 });
  }

  const form = JSON.parse(raw) as WebflowFormPayload;

  // Keyed on the submission id: a double-click, a retry or a replay that got
  // through cannot create a second lead for someone to de-duplicate by hand.
  await crm.upsertLead({
    idempotencyKey: `webflow:${form.id}`,
    email: form.data.email.trim().toLowerCase(),
    name: form.data.name,
    source: 'website',
  });

  return new Response(null, { status: 204 });
}
